/**
 * basemap-thumbnails.ts — REAL captures of the six live-monitoring basemaps
 * (QA A9).
 *
 * The layers switcher used to preview each style with a hand-drawn vector
 * miniature (`LiveBasemapPreview`'s palette swatches). Six abstract shapes
 * are not six basemaps: Satellite and Hybrid were near-indistinguishable, and
 * none of the tiles told the reader what the style actually looks like. These
 * are 88x88 screenshots of the ACTUAL rendered map over Doha, one per style
 * id, taken through the app itself so each carries that style's real tiles
 * AND its real canvas filter (`resolveGlobalBasemapCanvasFilter`) — which is
 * what makes Satellite (warm/dark) and Hybrid (cool/dark) read as siblings
 * rather than duplicates.
 *
 * Inlined as data URIs rather than shipped as asset files: the design system
 * is consumed as a compiled package by apps with their own bundlers and
 * public-asset conventions, and a relative image URL out of `dist/` resolves
 * differently in every one of them. Each is a 128-colour PNG under 4.5KB, so
 * all six together cost ~26KB of module text.
 *
 * REGENERATING: drive the live app to each basemap id, hide the markers and
 * the floating chrome, screenshot a 360px square of the canvas over Doha, and
 * downscale to 88x88 (2x the 44px tile). The captures must be marker-free —
 * a thumbnail with a pin baked into it reads as live data.
 *
 * token-exempt: these are basemap raster imagery being previewed, not themable
 * UI — the same carve-out `LiveBasemapPreview` and `VehicleIcon3D` document.
 */
export const LIVE_BASEMAP_THUMBNAILS: Record<string, string> = {
  grayscale:
    'data:image/png;base64,',
  osm:
    'data:image/png;base64,',
  roadmap:
    'data:image/png;base64,',
  satellite:
    'data:image/png;base64,',
  terrain:
    'data:image/png;base64,',
  hybrid:
    'data:image/png;base64,',
}
